"""Generate ``docs/cli.md`` from the Typer app (``make cli-docs``; ``tests/test_cli_docs.py`` fails if stale).

Built from the commands' parameters (Typer's click layer, read by duck typing since Typer vendors
click), not from rendered ``--help`` text, so the output doesn't depend on the terminal width.
"""

from __future__ import annotations

import inspect
from typing import Any

import typer

HEADER = """\
# CLI reference

<!-- Generated by `make cli-docs` from the argus-mint CLI. Do not edit by hand:
     tests/test_cli_docs.py fails when this file differs from the CLI. -->

`argus-mint` (or `python -m argus_mint`) needs the `cli` extra: `pip install "argus-mint[cli]"`.
Logs go to stderr; every command's result is JSON on stdout. Password prompts go to the terminal.

For the review flow these commands drive, see [drafts.md](drafts.md) and [review.md](review.md).
"""


def _is_option(p: Any) -> bool:
    return p.param_type_name == "option"


def _is_group(cmd: Any) -> bool:
    return hasattr(cmd, "list_commands")


def _first_paragraph(text: str | None) -> str:
    text = inspect.cleandoc(text or "")
    return text.split("\n\n", 1)[0].replace("\n", " ").strip()


def _help(text: str | None) -> str:
    """A command's whole docstring, paragraphs kept, Typer's ``\\b`` markers dropped."""
    paras = [p.replace("\b\n", "").replace("\n", " ").strip() for p in inspect.cleandoc(text or "").split("\n\n")]
    return "\n\n".join(p for p in paras if p)


def _cell(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def _default(p: Any) -> str:
    if _is_option(p) and p.is_flag and not p.secondary_opts:
        return ""
    d = p.default
    if d in (None, "", (), []) or callable(d) or (_is_option(p) and p.show_default is False):
        return ""
    if _is_option(p) and p.is_flag:
        return f"`{p.opts[0] if d else p.secondary_opts[0]}`"
    return f"`{d}`"


def _name(p: Any) -> str:
    if not _is_option(p):
        return f"`{_arg(p)}`"
    return ", ".join(f"`{o}`" for o in (*p.opts, *p.secondary_opts))


def _arg(p: Any) -> str:
    return p.name.upper()


def _usage(cmd: Any) -> str:
    args = [_arg(p) if p.required else f"[{_arg(p)}]" for p in cmd.params if not _is_option(p)]
    return " ".join(["[OPTIONS]", *args])


def _type(p: Any) -> str:
    if hasattr(p.type, "choices"):
        return " \\| ".join(f"`{c}`" for c in p.type.choices)
    return ""


def _params_table(cmd: Any) -> list[str]:
    params = [p for p in cmd.params if p.name != "help" and not getattr(p, "hidden", False)]
    if not params:
        return []
    rows = ["| Argument / option | Required | Default | Env | Help |", "|---|---|---|---|---|"]
    for p in params:
        env = p.envvar if isinstance(p.envvar, str) else ", ".join(p.envvar or ())
        helptext = getattr(p, "help", None) or ""
        if choices := _type(p):
            helptext = f"{helptext} (one of {choices})".strip()
        rows.append(
            "| "
            + " | ".join(
                [
                    _name(p),
                    "yes" if p.required else "",
                    _default(p),
                    f"`{env}`" if env else "",
                    _cell(helptext),
                ]
            )
            + " |"
        )
    return rows


def _walk(group: Any, prefix: str) -> list[tuple[str, Any]]:
    out: list[tuple[str, Any]] = []
    ctx = typer.Context(group)
    for name in group.list_commands(ctx):
        cmd = group.get_command(ctx, name)
        if cmd is None or cmd.hidden:
            continue
        full = f"{prefix} {name}"
        out.append((full, cmd))
        if _is_group(cmd):
            out += _walk(cmd, full)
    return out


def render(app: Any = None) -> str:
    """Markdown for every command of ``app`` (default: the argus-mint CLI)."""
    if app is None:
        from argus_mint.cli import app
    root = typer.main.get_command(app)
    commands = _walk(root, "argus-mint")
    lines = [HEADER, "## Commands", "", "| Command | What it does |", "|---|---|"]
    for full, cmd in commands:
        anchor = full.replace(" ", "-")
        lines.append(f"| [`{full}`](#{anchor}) | {_cell(_first_paragraph(cmd.help))} |")
    for full, cmd in commands:
        lines += ["", f"## {full}", ""]
        if body := _help(cmd.help):
            lines += [body, ""]
        if _is_group(cmd):
            lines.append("Subcommands: " + ", ".join(f"`{n}`" for n in cmd.list_commands(typer.Context(cmd))) + ".")
            continue
        lines += ["```", f"{full} {_usage(cmd)}", "```"]
        if table := _params_table(cmd):
            lines += ["", *table]
    return "\n".join(lines).rstrip() + "\n"
